mapper.insert:
insert into file_task_notification (
    file_task_id, target_type, target_user_id, recipient_user_ids, recipient_count,
    title, content, status, sender_user_id, send_time,
    create_by, create_time, update_by, update_time
) values (
    #{fileTaskId}, #{targetType}, #{targetUserId}, #{recipientUserIds}, #{recipientCount},
    #{title}, #{content}, #{status}, #{senderUserId}, #{sendTime},
    #{createBy}, #{createTime}, #{updateBy}, #{updateTime}
)

mapper.select:
select id, file_task_id, title, content, send_time
from file_task_notification
where file_task_id = #{taskId}
  and id = #{notificationId}
  and status = 'ACTIVE'
  and find_in_set(#{userId}, recipient_user_ids)

select file_task_id as fileTaskId, count(*) as notificationCount from file_task_notification where file_task_id in
#{taskId}
and status = 'ACTIVE' and find_in_set(#{userId}, recipient_user_ids) group by file_task_id
